import type { Recipe } from "../types";

type IngredientInput = [name: string, amount: string, note?: string];
type StepInput = [title: string, detail: string, why: string, tip?: string];
type Draft = Omit<Recipe, "ingredients" | "steps"> & {
  ingredients: IngredientInput[];
  steps: StepInput[];
};

const ka = (slug: string, title: string) => ({
  title: `King Arthur Baking: ${title}`,
  url: `https://www.kingarthurbaking.com/recipes/${slug}-recipe`,
});

function recipe(draft: Draft): Recipe {
  return {
    ...draft,
    reviewedOn: "2026-10-24",
    notes: [
      "Temperatures are for a preheated conventional oven. Times are checking ranges; use the stated doneness cues. Weigh ingredients for repeatable results.",
      "Reviewed against published baking references; this app's version has not yet been kitchen tested. Do not taste raw flour or raw-egg dough.",
      ...(draft.notes ?? []),
    ],
    ingredients: draft.ingredients.map(([name, amount, note], index) => ({
      id: `${draft.id}-ingredient-${index + 1}`, name, amount, ...(note ? { note } : {}),
    })),
    steps: draft.steps.map(([title, detail, why, tip], index) => ({
      id: `${draft.id}-step-${index + 1}`, title, detail, why, ...(tip ? { tip } : {}),
    })),
  };
}

